package dev.veltraph.client.mining;
import dev.veltraph.client.config.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class MiningCraftLoanTest {
    @Test void exactResourceLoanGatesAllEngineCallbacksAndCannotOverlapScheduling(){var s=new MiningControllerTest.Services();var engine=new MiningController(MiningMode.COBBLESTONE,s,new MapConfigService());engine.start();Object loan=new Object();assertTrue(engine.beginOwnedSubflow(loan));int stops=s.stopped;s.input.jump=true;for(int i=0;i<20;i++){engine.tick();engine.stop();engine.resetAtRewarp();}assertTrue(s.input.jump);assertEquals(stops,s.stopped);assertFalse(engine.allowsTarget(MiningControllerTest.TARGET));assertFalse(engine.scheduledBoundary());assertFalse(engine.pauseForScheduledRest(new Object()));assertFalse(engine.endOwnedSubflow(new Object()));assertThrows(IllegalStateException.class,engine::start);assertTrue(engine.endOwnedSubflow(loan));assertFalse(engine.endOwnedSubflow(loan));engine.tick();assertEquals(MiningController.State.BREAKING,engine.state());}
    @Test void changedWorldCannotBorrowOrResumeTheOldEngine(){var s=new MiningControllerTest.Services();var e=new MiningController(MiningMode.COBBLESTONE,s,new MapConfigService());e.start();s.identity="new world";assertFalse(e.beginOwnedSubflow(new Object()));s.identity="world one";Object token=new Object();assertTrue(e.beginOwnedSubflow(token));s.identity="new world";assertTrue(e.endOwnedSubflow(token));e.tick();assertEquals(MiningController.State.PAUSED,e.state());assertFalse(e.beginOwnedSubflow(new Object()));}
    @Test void cobbleLoanUsesObservedInventoryBoundaryWithoutWaitingThirtyFrames(){var s=new MiningControllerTest.Services();var e=new MiningController(MiningMode.COBBLESTONE,s,new MapConfigService());e.start();e.tick();assertFalse(e.beginOwnedSubflow(new Object()));s.id="minecraft:air";assertTrue(e.observeCobbleInventoryBoundary());assertFalse(e.observeCobbleInventoryBoundary());assertEquals(1,e.removed());assertTrue(e.ownedSubflowReady());assertTrue(e.beginOwnedSubflow(new Object()));}
    @Test void mineDownLoanStillWaitsForDropSettling(){var s=new MiningControllerTest.Services();var e=new MiningController(MiningMode.MINE_DOWN,s,new MapConfigService());e.start();e.tick();assertFalse(e.beginOwnedSubflow(new Object()));s.id="minecraft:air";e.tick();assertFalse(e.beginOwnedSubflow(new Object()));for(int i=0;i<29;i++)e.tick();assertTrue(e.ownedSubflowReady());}
}
